  "sim.revolution.18": "Constitution of {nm}",
  "sim.revolution.19": "We the people, carrying on the spirit of the revolution that rose against dictatorship, enact this constitution to firmly establish a free and democratic basic order and to protect the dignity and rights of all citizens.",
  "sim.revolution.20": "Popular sovereignty",
  "sim.revolution.21": "Sovereignty rests with the people, and all power comes from the people.",
  "sim.revolution.22": "Fundamental rights",
  "sim.revolution.23": "All citizens have human dignity and worth, and the state has the duty to confirm and guarantee the inviolable fundamental human rights of individuals.",
  "sim.revolution.24": "Multi-party system",
  "sim.revolution.25": "Parties may be founded freely, and the multi-party system is guaranteed.",
  "sim.revolution.26": "Members of parliament and the head of state are chosen by universal, equal, direct and secret ballot.",
  "sim.revolution.27": "Separation of powers",
  "sim.revolution.28": "Legislative power belongs to parliament, executive power to the government, and judicial power to the courts.",
  "sim.revolution.29": "Limits on martial law",
  "sim.revolution.30": "Martial law may not exceed 60 days without the consent of parliament, and parliament's work is not suspended during martial law.",
  "sim.revolution.31": "Socialist Constitution of {nm}",
  "sim.revolution.32": "Our country",
  "sim.revolution.33": "{nm} is a people's state founded by revolution under the leadership of {name}. The people adopt this constitution to carry on the great work of the revolution and complete the building of socialism.",
  "sim.revolution.34": "Character of the state",
  "sim.revolution.35": "{nm} is a socialist state representing the interests of the whole people, including workers, peasants and the working intelligentsia.",
  "sim.revolution.36": "Leadership of the party",
  "sim.revolution.37": "The state conducts all its activities under the leadership of {name}.",
  "sim.revolution.38": "United front",
  "sim.revolution.39": "The state forms a united front with friendly parties and social organizations that support the revolution.",
  "sim.revolution.40": "Supreme organ of power",
  "sim.revolution.41": "The Supreme People's Assembly is the supreme organ of state power.",
  "sim.revolution.42": "President of the state",
  "sim.revolution.43": "The President is the head of state and is concurrently the general secretary of the party.",
  "sim.revolution.44": "Deputies to the Supreme People's Assembly are elected by a yes/no vote on single candidates nominated by the united front.",
  "sim.revolution.45": "Council Constitution of {nm}",
  "sim.revolution.46": "{nm} is a council state of workers and the people, founded together by the revolutionary coalition of {names}. The people adopt this constitution to build socialism while freely debating and contending over the path of the revolution.",
  "sim.revolution.47": "{nm} is a socialist state governed by councils of workers, peasants and working people.",
  "sim.revolution.48": "Revolutionary coalition",
