  "sim.royal.16": "As head of state the monarch holds all sovereign power, and appoints and dismisses the prime minister and ministers.",
  "sim.royal.17": "Parliament assists the monarch, and laws take effect with the monarch's sanction. The monarch may veto bills.",
  "sim.royal.18": "Emergency prerogative",
  "sim.royal.19": "In a national emergency the monarch may declare martial law and prorogue or dissolve parliament.",
  "sim.royal.20": "Succession to the throne",
