  "sim.royal.23": "Constitution of {nm}",
  "sim.royal.24": "Our country",
  "sim.royal.25": "{nm} is a constitutional monarchy that honors the monarch of {house} as the symbol of the state, and sovereignty rests with the people.",
  "sim.royal.26": "Form of state",
  "sim.royal.27": "{nm} is a constitutional monarchy. The monarch is the symbol of the state and the unity of the people and holds no real power over state affairs.",
  "sim.royal.28": "Popular sovereignty",
  "sim.royal.29": "Sovereignty rests with the people, and all power comes from the people.",
  "sim.royal.30": "Executive power is vested in the cabinet, and the prime minister rests on the confidence of parliament.",
  "sim.royal.31": "We the people, abolishing the monarchy and founding a republic in which all citizens are sovereign, enact this constitution to uphold an order of liberty and equality.",
  "sim.royal.32": "{nm} is a democratic republic.",
