  "maker.campaignEditor.131": "Open editor →",
  "maker.campaignEditor.132": "How to build a scenario",
  "maker.campaignEditor.133": "— a built-in preset or a full preset (.hemi) made in the game. With several countries, the player picks one at the start.",
  "maker.campaignEditor.134": "— a choice that takes days to finish. When done, its effects apply and the flag",
  "maker.campaignEditor.135": " turns on.",
  "maker.campaignEditor.136": "— starts on a date · condition (e.g. a direction finished). Gauges are variables, moved with the effect",
  "maker.campaignEditor.137": " and read in ending conditions with",
  "maker.campaignEditor.138": ". When it ends, the flag",
  "maker.campaignEditor.139": "— when the condition is met, the scenario ends and the ending screen appears (you can keep playing after).",
  "maker.campaignEditor.140": "Test play",
  "maker.campaignEditor.141": "— right in the game: the \"Scenario\" tab at the top (overview · directions · upheavals) and the \"Scenario\" view on the right (direction tree · upheavals).",
  "maker.campaignEditor.142": "Guide mode builds conditions and effects with fields. Switch to Pro mode to edit the same data directly as JSON. Custom rules are kept as they are.",
  "maker.campaignEditor.143": "Full preset = a whole country game. Set up the starting situation in the game and use a file from Save › Save to file (.hemi), or a built-in preset.",
