  "map.main.1": "Back to creations",
  "map.main.2": "← Creations",
  "map.main.3": "Turn SVG · images (webp · png · jpg · bmp, auto-traced) · .jsx · .hemimap maps into a district map (.jsx — shapes only) or a district preset (.hemimap — shapes · names · abbreviations · seats · population) — load the files in the game under Nation › District map",
  "map.main.4": "SVG · images (webp · png · jpg · bmp) · .jsx made by the Map Maker · .hemimap district preset",
  "map.main.5": "⬆ Open map",
  "map.main.6": "Save project",
  "map.main.7": "Clear the open map and the list",
  "map.main.8": "Project name",
  "map.main.9": "Saved automatically once a map is open.",
  "map.main.10": "Scroll: zoom · Middle-drag: pan · Click: select",
  "map.main.11": "Use SVG shape ids · labels as district names (off: name by shape order)",
  "map.main.12": "Prefer id/label",
  "map.main.13": "Raster auto-trace",
  "map.main.14": "A small map with each pixel painted an exact color (province maps, etc.) — pixels of exactly the same color become one region, traced along pixel edges without growing, removing small bits or smoothing borders. Turns on automatically when you open such an image",
  "map.main.15": "Pixel map",
  "map.main.16": "On a pixel map, pixels of the same color form one region even when apart (islands · exclaves) — turn on for province maps with one color per region. Off: each connected blob is separate",
  "map.main.17": "Same color = one region even if apart",
  "map.main.18": "Colors this different still count as the same region. Re-traces automatically when you stop moving it — raise it if regions split into bits, lower it if neighbors merge",
  "map.main.19": "Color tolerance",
  "map.main.20": "Blobs smaller than this (text · blurred edges) join a neighboring region — per mille of the image area",
  "map.main.21": "Min size",
  "map.main.22": "Leave out the large blob around the image edge (sea · background)",
  "map.main.23": "Drop background",
  "map.main.24": "Join same-colored touching pieces without black lines between them (compression smudges · pieces split by faint slightly-different lines) — areas split by black lines aren't merged. Off: keep the pieces",
  "map.main.25": "Merge same-color neighbors",
  "map.main.26": "Trace again",
  "map.main.27": "① ⬆ Open map (analyzed right away) → ② edit names · abbreviations · seats · population and select in the list on the right → ③ export (.jsx — shapes only) or district preset (.hemimap — shapes · names · seats · population)",
  "map.main.28": "SVG is the most accurate. Images like webp · png · jpg · bmp are pixels with no shapes, so shapes are traced automatically along same-colored blobs (works best for maps with clear borders and a different color per region). You can reopen and edit a .jsx made by the Map Maker too.",
  "map.main.29": "If separate pieces of land are bundled into one shape, split them with ✂ in the list; select shapes of the same district to merge them",
  "map.main.30": "District list",
  "map.main.31": "Shapes",
  "map.main.32": "· selected",
  "map.main.33": "Merge the selected shapes into one district",
  "map.main.34": "Merge",
  "map.main.35": "Show abbreviation · seats · population fields for each district in the list (saved in the .hemimap district preset)",
  "map.main.36": "Show abbreviation · seats · population fields",
  "map.main.37": "File name for exports (.hemimap · .jsx · .svg is added automatically)",
  "map.main.38": "File name",
  "map.main.39": "Shapes · names · abbreviations · seats · population — recommended",
  "map.main.40": "All districts as a district preset (.hemimap) — the map shapes plus names · abbreviations · seats · population; upload it under Nation › District map in the game to bring it all in at once",
